/* Lot 106: Oklab interpolation of registered <color> values unless both are legacy sRGB (generated by scripts/lot106_gen.py; expectations from scripts/lot106_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;
static char g_o[320];

/* currentcolor is teal (wf_cssprop_set_current) */
static int syn(const char *s) {
    wf_cssprop_set_current(1, 0x008080u, 255);
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(s, (int)strlen(s), &g_p);
    return g_p.syntax != 0;
}

/* the interpolated text of two colours; the return code is checked */
static const char *ip(const char *a, const char *b, int t, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_interp(&g_p, a, b, t, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static const char *ipl(const char *a, const char *b, int t, int code) {
    if (!syn("'<color>+'")) return "BAD SYNTAX";
    if (wf_cssprop_interp(&g_p, a, b, t, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static const char *ad(const char *a, const char *b, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_add(&g_p, a, b, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

/* accumulate is add for colours (Lot 99) */
static const char *ac(const char *a, const char *b, int code) {
    if (!syn("'<color>'")) return "BAD SYNTAX";
    if (wf_cssprop_accumulate(&g_p, a, b, g_o, (int)sizeof(g_o)) != code) return "BAD CODE";
    return g_o;
}

static void test_l106_interp_0(void) {
    TEST_ASSERT_EQUAL_STRING("rgb(227, 218, 255)", ip("hwb(284.2537deg 40 none /1.5)", "oklch(0.5 0.2 none)", -10000, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgba(25, 128, 128, 0.8334)", ip("currentcolor", "hwb(16 50% 50% / 50%)", 3333, 2));   /* srgb */
    TEST_ASSERT_EQUAL_STRING("rgb(37, 0, 0)", ip("oklab(0 0.2430 0.2353)", "hsl(none 100% 50%)", 2500, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgb(102, 52, 152)", ip("lab(none 0 0)", "rebeccapurple", 9900, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgba(0, 0, 0, 0)", ip("rebeccapurple", "transparent", 12500, 2));   /* srgb */
    TEST_ASSERT_EQUAL_STRING("rgb(232, 47, 238)", ip("color-mix(in oklch, red, blue)", "lab(66.86 none none)", 7500, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgb(59, 107, 0)", ip("color-mix(in hwb, lch(80.57 16.19 80.18), lab(93.74 10.23 none))", "hwb(81.9 13 50%)", 12500, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgb(224, 162, 115)", ip("hwb(30 10% 20%)", "oklab(1 0 0)", 3333, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgb(255, 255, 255)", ip("hwb(503.4grad 35.2645% 71.9%)", "hwb(1.184turn 100% 6%)", 20000, 2));   /* srgb */
    TEST_ASSERT_EQUAL_STRING("rgba(183, 0, 190, 0.6669)", ip("color-mix(in oklch, red, blue)", "transparent", 3331, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgba(255, 255, 255, 0.2528)", ip("hwb(0rad 93 101.3%)", "color( xyz-d65 0.426 0.4 0.574 / 0.6264)", 20000, 2));   /* oklab */
    TEST_ASSERT_EQUAL_STRING("rgba(255, 0, 0, 0.995)", ip("color(rec2020 1 0 0 / 0.5)", "hsl(none 100% 50%)", 9900, 2));   /* oklab */
}

